mapper.select:
SELECT a.ID, a.TITLE, a.SUMMARY, a.ARTICLE_TYPE, a.ARTICLE_PERM, a.ARTICLE_STATUS, a.COMMENT_FLAG, a.WORDS_COUNT, a.VIEW_COUNT, a.COMMENT_COUNT, a.AUTHOR_ID, a.UPDATE_TIME, a.VERSION, a.DELETE_FLAG, a.COVER_IMAGE_TYPE, u.NICKNAME AS AUTHOR_NAME, c.NAME AS CATEGORY_NAME, av.PUBLISH_TIME FROM article a LEFT JOIN category c ON c.ID = a.CATEGORY_ID LEFT JOIN user u ON u.ID = a.AUTHOR_ID LEFT JOIN article_version av ON av.ARTICLE_ID = a.ID AND av.VERSION = a.VERSION WHERE a.AUTHOR_ID = #{query.authorId}
AND a.DELETE_FLAG = 0
AND a.DELETE_FLAG = 0 AND a.ARTICLE_STATUS = 1
AND a.DELETE_FLAG = 0 AND a.ARTICLE_PERM = 3
AND a.DELETE_FLAG = 0 AND a.ARTICLE_STATUS = 5 AND a.ARTICLE_PERM != 3
AND a.DELETE_FLAG = 0 AND a.ARTICLE_STATUS = 2
AND a.DELETE_FLAG = 0 AND a.ARTICLE_STATUS = 3
AND a.DELETE_FLAG = 0 AND a.ARTICLE_STATUS IN (4, 91)
AND a.DELETE_FLAG = 1
AND a.ARTICLE_STATUS = -1
AND a.TITLE LIKE #{titleBind}
AND a.SLUG = #{query.slug}
AND a.CATEGORY_ID = #{query.categoryId}
AND a.ID IN (SELECT ARTICLE_ID FROM article_tag_relation atr WHERE atr.TAG_ID = #{query.tagId})
AND a.ARTICLE_TYPE = #{query.articleType}
AND a.ARTICLE_STATUS = #{query.articleStatus}
AND a.COMMENT_FLAG = #{query.commentFlag}
ORDER BY a.UPDATE_TIME DESC

SELECT atr.ARTICLE_ID AS articleId, t.NAME AS tagName FROM article_tag_relation atr INNER JOIN tag t ON t.ID = atr.TAG_ID WHERE atr.DELETED = 0 AND atr.ARTICLE_ID IN
#{articleId}
ORDER BY atr.ARTICLE_ID, atr.TAG_ID

SELECT air.ARTICLE_ID AS articleId, air.ARTICLE_IMAGE AS coverImage FROM article_image_relation air WHERE air.ARTICLE_ID IN
#{articleId}
ORDER BY air.ARTICLE_ID, air.ARTICLE_IMAGE
